INSERT INTO articles (title, slug, category, city, state, country, author, views, status, date, excerpt, content, featuredImage, ogImage, metaTitle, metaDescription, tags, featured, newsType, journalistId, journalistName, access_level) VALUES ('অসমে বন্যা পরিস্থিতি আরও ভয়াবহ, লক্ষাধিক মানুষ ক্ষতিগ্রস্ত', 'bn-1-1788869021517-9a7c', 'NORTHEAST', NULL, NULL, NULL, NULL, 385, 'Published', '2026-08-12 11:33:42.000', 'অসমের বন্যা পরিস্থিতি ক্রমশ অবনতি হচ্ছে। রাজ্যের বত্রিশটি জেলায় প্রায় পনেরো লক্ষ মানুষ বন্যায় ক্ষতিগ্রস্ত হয়েছেন।', '<p>অসমের বন্যা পরিস্থিতি ক্রমশ অবনতি হচ্ছে। রাজ্যের বত্রিশটি জেলায় প্রায় পনেরো লক্ষ মানুষ বন্যায় ক্ষতিগ্রস্ত হয়েছেন।</p>', NULL, NULL, 'অসমে বন্যা পরিস্থিতি আরও ভয়াবহ, লক্ষাধিক মানুষ ক্ষতিগ্রস্ত', 'অসমের বন্যা পরিস্থিতি ক্রমশ অবনতি হচ্ছে। রাজ্যের বত্রিশটি জেলায় প্রায় পনেরো লক্ষ মানুষ বন্যায় ক্ষতিগ্রস্ত হয়েছেন।', 'বন্যা,অসম,দুর্যোগ', 1, 'Breaking', NULL, NULL, 'Free');
INSERT INTO articles (title, slug, category, city, state, country, author, views, status, date, excerpt, content, featuredImage, ogImage, metaTitle, metaDescription, tags, featured, newsType, journalistId, journalistName, access_level) VALUES ('মেঘালয়ে নতুন পর্যটন সার্কিট উদ্বোধন, বাড়বে কর্মসংস্থান', 'bn-2-1788869021520-2qd9', 'NORTHEAST', NULL, NULL, NULL, NULL, 56, 'Published', '2026-08-25 05:33:42.000', 'মেঘালয় সরকার রাজ্যে নতুন পর্যটন সার্কিট চালু করল। স্থানীয় মানুষের কর্মসংস্থান বাড়বে বলে আশা।', '<p>মেঘালয় সরকার রাজ্যে নতুন পর্যটন সার্কিট চালু করল। স্থানীয় মানুষের কর্মসংস্থান বাড়বে বলে আশা।</p>', NULL, NULL, 'মেঘালয়ে নতুন পর্যটন সার্কিট উদ্বোধন, বাড়বে কর্মসংস্থান', 'মেঘালয় সরকার রাজ্যে নতুন পর্যটন সার্কিট চালু করল। স্থানীয় মানুষের কর্মসংস্থান বাড়বে বলে আশা।', 'মেঘালয়,পর্যটন,কর্মসংস্থান', 1, 'Standard', NULL, NULL, 'Free');
